def rotting_oranges(grid):
    from collections import deque
    rows, cols = len(grid), len(grid[0])
    queue = deque()
    fresh = 0

    # Enqueue all rotten, count fresh
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "R": queue.append((r, c))
            elif grid[r][c] == "F": fresh += 1

    minutes = 0
    dirs = [(0,1),(0,-1),(1,0),(-1,0)]

    while queue and fresh > 0:
        minutes += 1
        for _ in range(len(queue)):  # level-by-level
            r, c = queue.popleft()
            for dr, dc in dirs:
                nr, nc = r+dr, c+dc
                if 0<=nr<rows and 0<=nc<cols and grid[nr][nc]=="F":
                    grid[nr][nc] = "R"
                    fresh -= 1
                    queue.append((nr, nc))

    return minutes if fresh == 0 else -1
